import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        new Executor().solve();
    }

    static class Executor {
        void solve() {
            InputReader in = new InputReader(System.in);
            PrintWriter out = new PrintWriter(System.out);
            final int MOD = 998244353;
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; ++i) {
                v[in.nextInt()] = 1;
            }
            int[] ans = {1};
            int exp = n >> 1;
            while (exp > 0) {
                if ((exp & 1) == 1) ans = mul(ans, v, MOD);
                exp >>= 1;
                if (exp > 0) v = mul(v, v, MOD);
            }
            long total = 0;
            for (int val : ans) total = (total + (long) val * val) % MOD;
            out.println((int) total);
            out.close();
        }

        static int[] mul(int[] a, int[] b, int mod) {
            int need = a.length + b.length - 1;
            int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);
            double[] ar = new double[n], ai = new double[n];
            for (int i = 0; i < a.length; ++i) {
                int x = (a[i] % mod + mod) % mod;
                ar[i] = x & 0x7FFF;
                ai[i] = x >> 15;
            }
            fft(ar, ai, false);
            double[] br = new double[n], bi = new double[n];
            if (a == b) {
                System.arraycopy(ar, 0, br, 0, n);
                System.arraycopy(ai, 0, bi, 0, n);
            } else {
                for (int i = 0; i < b.length; ++i) {
                    int x = (b[i] % mod + mod) % mod;
                    br[i] = x & 0x7FFF;
                    bi[i] = x >> 15;
                }
                fft(br, bi, false);
            }
            double[] cr = new double[n], ci = new double[n];
            double[] dr = new double[n], di = new double[n];
            double inv = 0.25 / n;
            for (int i = 0; i < n; ++i) {
                int j = (n - i) & (n - 1);
                double a1r = ar[i] + ar[j], a1i = ai[i] - ai[j];
                double a2r = ai[i] + ai[j], a2i = ar[j] - ar[i];
                double b1r = (br[i] + br[j]) * inv, b1i = (bi[i] - bi[j]) * inv;
                double b2r = (bi[i] + bi[j]) * inv, b2i = (br[j] - br[i]) * inv;
                cr[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
                ci[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
                dr[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
                di[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
            }
            fft(cr, ci, true);
            fft(dr, di, true);
            int[] res = new int[need];
            for (int i = 0; i < need; ++i) {
                long rr = (long) (cr[i] + 0.5);
                long ss = (long) (dr[i] + 0.5);
                long tt = (long) (ci[i] + 0.5);
                res[i] = (int) ((rr + ((ss % mod) << 15) + ((tt % mod) << 30)) % mod);
            }
            return res;
        }

        static void fft(double[] re, double[] im, boolean inv) {
            int n = re.length;
            int shift = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; ++i) {
                int j = Integer.reverse(i << shift);
                if (i < j) {
                    double t = re[i]; re[i] = re[j]; re[j] = t;
                    t = im[i]; im[i] = im[j]; im[j] = t;
                }
            }
            for (int len = 2; len <= n; len <<= 1) {
                int half = len >> 1;
                double[] cos = new double[half], sin = new double[half];
                for (int i = 0; i < half; ++i) {
                    cos[i] = Math.cos(2 * Math.PI * i / len * (inv ? -1 : 1));
                    sin[i] = Math.sin(2 * Math.PI * i / len * (inv ? -1 : 1));
                }
                for (int i = 0; i < n; i += len) {
                    for (int j = 0; j < half; ++j) {
                        double uR = re[i + j], uI = im[i + j];
                        double vR = re[i + j + half] * cos[j] - im[i + j + half] * sin[j];
                        double vI = re[i + j + half] * sin[j] + im[i + j + half] * cos[j];
                        re[i + j] = uR + vR;
                        im[i + j] = uI + vI;
                        re[i + j + half] = uR - vR;
                        im[i + j + half] = uI - vI;
                    }
                }
            }
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1)
                throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0)
                    return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
